    /** private_state stays in callback memory; the host owns native backups and failure stages. */
    public static function before(PDO $pdo,array $migration): array
    {
        $id=$migration['id']??null; $sql=$migration['sql']??null; $sha=$migration['checksum']??$migration['sha256']??null;
        if (!is_string($id)||!isset(self::SOURCES[$id])||!is_string($sql)||$sha!==self::SOURCES[$id]||!hash_equals($sha,hash('sha256',$sql))||(isset($migration['sha256'])&&$migration['sha256']!==$sha)) { self::fail('SOURCE_UNKNOWN'); }
        return self::snapshot($pdo,static function () use ($pdo,$id,$sha): array {
            $state=match ($id) {
                '20261004-group-default-navigation'=>self::beforeNavigation($pdo),
                '20261004-menu-stable-identities'=>self::beforeIdentities($pdo),
                '20261012-repair-seeded-permission-parents'=>self::beforeRepair($pdo),
            };
            return ['migration_id'=>$id,'source_sha256'=>$sha,'readonly'=>true,
                'private_state'=>['pdo_object_id'=>spl_object_id($pdo),'connection'=>self::connection($pdo),'business'=>$state],
                'safe_summary'=>['migration_id'=>$id,'source_sha256'=>$sha,'readonly'=>true,'protected_checks'=>count($state['checks']),'candidate_count'=>count($state['candidates'])]];
        });
    }

    public static function after(PDO $pdo,array $before): array
    {
        $id=$before['migration_id']??null; $private=$before['private_state']??null;
        if (!is_string($id)||!isset(self::SOURCES[$id])||($before['source_sha256']??null)!==self::SOURCES[$id]||!is_array($private)||($private['pdo_object_id']??null)!==spl_object_id($pdo)||!is_array($private['business']??null)) { self::fail('INPUT_INVALID'); }
        return self::snapshot($pdo,static function () use ($pdo,$id,$private): array {
            if ($private['connection']!==self::connection($pdo)) { self::fail('CONNECTION_CHANGED'); }
            $state=$private['business'];
            foreach ($state['checks'] as $check) { if (self::digest($pdo,$check['after'])!==$check['digest']) { self::fail('PROTECTED_FIELDS_CHANGED'); } }
            match ($id) {
                '20261004-group-default-navigation'=>self::afterNavigation($pdo,$state),
                '20261004-menu-stable-identities'=>self::afterIdentities($pdo,$state),
                '20261012-repair-seeded-permission-parents'=>self::afterRepair($pdo,$state),
            };
            return ['migration_id'=>$id,'source_sha256'=>self::SOURCES[$id],'readonly'=>true,'business_postconditions_verified'=>true,'protected_checks'=>count($state['checks'])];
        });
    }

    private static function beforeNavigation(PDO $pdo): array
    {
        $system=self::columns($pdo,'pa_system_menu'); $definition=self::columns($pdo,'pa_menu_definition');
        $defaults=self::column($system,'upstream_defaults_json','NULL'); $conflict=self::column($system,'menu_conflict_json','NULL');
        $baseline="COALESCE($defaults,".self::SYSTEM_DEFAULTS.')'; $directories=[];
        foreach (['/system-settings','/operations'] as $path) {
            // The source counts managed rows only. Several custom path rows plus one managed row still select that one.
            $directories[$path]=self::query($pdo,'SELECT COUNT(*) AS path_count,SUM('.self::live()."=$baseline) AS managed_count,MIN(IF(".self::live()."=$baseline,id,NULL)) AS managed_id FROM pa_system_menu WHERE paths=".$pdo->quote($path))[0];
        }
        $max=(string)self::query($pdo,'SELECT COALESCE(MAX(id),0) AS id FROM pa_system_menu')[0]['id']; $checks=[];
        self::protect($pdo,$checks,'pa_system_menu',$system,['pid','name','upstream_defaults_json','menu_conflict_json'],"id<=$max");
        self::protect($pdo,$checks,'pa_menu_definition',$definition,['upstream_defaults_json']);
        self::check($pdo,$checks,'SELECT id,pid,name FROM pa_system_menu WHERE id NOT IN ('.self::NODE_IDS.') ORDER BY id',"SELECT id,pid,name FROM pa_system_menu WHERE id<=$max AND id NOT IN (".self::NODE_IDS.') ORDER BY id');
        self::check($pdo,$checks,"SELECT id,$baseline AS v FROM pa_system_menu WHERE id NOT IN (".self::NODE_IDS.') ORDER BY id',"SELECT id,upstream_defaults_json AS v FROM pa_system_menu WHERE id<=$max AND id NOT IN (".self::NODE_IDS.') ORDER BY id');
        $def=self::column($definition,'upstream_defaults_json','NULL');
        self::check($pdo,$checks,"SELECT id,COALESCE($def,".self::DEFINITION_DEFAULTS.') AS v FROM pa_menu_definition ORDER BY id','SELECT id,upstream_defaults_json AS v FROM pa_menu_definition ORDER BY id');
        $marker="CASE WHEN $baseline IS NOT NULL AND ".self::live()."<>$baseline THEN JSON_OBJECT('reason','legacy_default_mismatch') ELSE $conflict END";
        self::check($pdo,$checks,"SELECT id,$marker AS v FROM pa_system_menu WHERE id NOT IN (".self::NODE_IDS.') ORDER BY id',"SELECT id,menu_conflict_json AS v FROM pa_system_menu WHERE id<=$max AND id NOT IN (".self::NODE_IDS.') ORDER BY id');
        $candidates=self::query($pdo,'SELECT id,pid,name,'.self::live()." AS live,$baseline AS defaults,$conflict AS conflict FROM pa_system_menu WHERE id IN (".self::NODE_IDS.') ORDER BY id');
        $parents=[];
        foreach ([1,20,30,38,40,45] as $id) { $parents[$id]=self::managed($pdo,$id,$baseline); }
        return ['checks'=>$checks,'candidates'=>$candidates,'directories'=>$directories,'parents'=>$parents,'max_id'=>$max,'row_count'=>(int)self::query($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu')[0]['n']];
    }

    private static function afterNavigation(PDO $pdo,array $state): void
    {
        foreach (['pa_system_menu','pa_menu_definition'] as $table) { self::requireColumns($pdo,$table,['upstream_defaults_json'=>'json','menu_conflict_json'=>'json']); }
        $directoryIds=[]; $parents=$state['parents']; $candidates=$state['candidates'];
        $new=self::query($pdo,'SELECT id,paths FROM pa_system_menu WHERE id>'.$state['max_id']);
        $missing=array_keys(array_filter($state['directories'],static fn(array $v): bool=>(int)$v['path_count']===0));
        if (count($new)!==count($missing)) { self::fail('DIRECTORY_INSERT_COUNT'); }
        foreach ($new as $row) {
            if (!in_array($row['paths'],$missing,true)) { self::fail('UNEXPECTED_INSERT'); }
            $settings=$row['paths']==='/system-settings';
            $name=$pdo->quote($settings?'系统设置':'运维与审计'); $icon=$pdo->quote($settings?'icon-settings':'icon-history'); $sort=$settings?30:20;
            $newId=(int)$row['id']; $directoryIds[$row['paths']]=$newId; $parents[$newId]=true;
            self::assertZero($pdo,"SELECT COUNT(*) AS n FROM pa_system_menu WHERE id=$newId AND NOT (type='M' AND BINARY icon=BINARY $icon AND sort=$sort AND perms='' AND component='' AND is_cache=0 AND is_show=1 AND is_disable=0)");
            if (isset(self::TARGETS[$newId])) {
                // A real allocated ID may coincide with a historical selector. Check that finite node too; never predict the ID.
                $json=self::query($pdo,"SELECT JSON_OBJECT('pid',0,'type','M','name',$name,'icon',$icon,'sort',$sort,'perms','','paths',".$pdo->quote($row['paths']).",'component','','is_cache',0,'is_show',1,'is_disable',0) AS v")[0]['v'];
                $candidates[]=['id'=>$newId,'pid'=>0,'name'=>$settings?'系统设置':'运维与审计','live'=>$json,'defaults'=>$json,'conflict'=>null];
            } else {
                self::assertZero($pdo,"SELECT COUNT(*) AS n FROM pa_system_menu WHERE id=$newId AND NOT (pid=0 AND BINARY name=BINARY $name AND ".self::live().'=upstream_defaults_json AND menu_conflict_json IS NULL)');
            }
        }
        foreach ($state['directories'] as $path=>$directory) {
            $rows=self::query($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu WHERE paths='.$pdo->quote($path));
            if ((int)$rows[0]['n']!==(int)$directory['path_count']+((int)$directory['path_count']===0?1:0)) { self::fail('DIRECTORY_SET_CHANGED'); }
            if ((int)$directory['path_count']!==0) { $directoryIds[$path]=(int)$directory['managed_count']===1?(int)$directory['managed_id']:null; }
        }
        if ((int)self::query($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu')[0]['n']!==$state['row_count']+count($missing)) { self::fail('NODE_COUNT_CHANGED'); }
        foreach ($candidates as $node) {
            $id=(int)$node['id']; $target=self::TARGETS[$id]; $pid=is_string($target[0])?$directoryIds[$target[0]]:$target[0];
            $targetJson='('.self::TARGET_DEFAULTS.')';
            if ($id===37) { $targetJson="JSON_SET($targetJson,'$.pid',".($pid===null?'NULL':(string)$pid).')'; }
            $live=$pdo->quote((string)$node['live']); $defaults=$node['defaults']===null?'NULL':$pdo->quote((string)$node['defaults']); $conflict=$node['conflict']===null?'NULL':$pdo->quote((string)$node['conflict']);
            $sourceManaged=$target[2]===0||($parents[$target[2]]??false);
            $targetManaged=$pid!==null&&($pid===0||($parents[$pid]??false)||is_string($target[0]));
            $eligible=$sourceManaged&&$targetManaged&&(string)self::query($pdo,"SELECT CAST($live AS JSON)=CAST($defaults AS JSON) AS yes")[0]['yes']==='1';
            $expectedDefaults=$eligible?$targetJson:"CAST($defaults AS JSON)"; $expectedPid=$eligible?$pid:(int)$node['pid']; $name=$pdo->quote((string)($eligible?$target[1]:$node['name']));
            $marker="CASE WHEN $expectedDefaults IS NOT NULL AND ".self::live()."<>$expectedDefaults THEN JSON_OBJECT('reason','legacy_default_mismatch') WHEN ".self::live()."=$expectedDefaults AND $expectedDefaults<>$targetJson THEN JSON_OBJECT('reason','navigation_parent_conflict') ELSE ".($eligible?'NULL':"CAST($conflict AS JSON)").' END';
            self::assertZero($pdo,"SELECT COUNT(*) AS n FROM pa_system_menu WHERE id=$id AND NOT (pid=$expectedPid AND BINARY name=BINARY $name AND upstream_defaults_json<=>$expectedDefaults AND menu_conflict_json<=>($marker))");
        }
        self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu WHERE upstream_defaults_json IS NOT NULL AND '.self::live()."<>upstream_defaults_json AND NOT (menu_conflict_json<=>JSON_OBJECT('reason','legacy_default_mismatch'))");
    }

    private static function beforeIdentities(PDO $pdo): array
    {
        $system=self::columns($pdo,'pa_system_menu'); $definition=self::columns($pdo,'pa_menu_definition');
        $key=self::column($system,'menu_key','NULL'); $parent=self::column($system,'parent_key','NULL'); $module=self::column($system,'module_key',"'application'");
        $matches="SELECT m.id,s.menu_key,s.module_key FROM pa_system_menu m JOIN (".self::IDENTITY_SEEDS.") s ON m.type COLLATE utf8mb4_unicode_ci=s.type AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(m.upstream_defaults_json,'$.paths')),m.paths) COLLATE utf8mb4_unicode_ci=s.paths AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(m.upstream_defaults_json,'$.perms')),m.perms) COLLATE utf8mb4_unicode_ci=s.perms";
        $canonical=self::query($pdo,"SELECT a.id,a.menu_key,a.module_key FROM ($matches) a JOIN (SELECT menu_key,MIN(id) AS id FROM ($matches) b GROUP BY menu_key HAVING COUNT(*)=1) u ON u.id=a.id AND u.menu_key=a.menu_key JOIN pa_system_menu m ON m.id=a.id WHERE ".(isset($system['menu_key'])?'m.menu_key':'NULL').' IS NULL ORDER BY a.id');
        $nullIds=array_column(self::query($pdo,"SELECT id FROM pa_system_menu WHERE $key IS NULL ORDER BY id"),'id'); $parentIds=array_column(self::query($pdo,"SELECT id FROM pa_system_menu WHERE $parent IS NULL AND pid<>0 ORDER BY id"),'id'); $checks=[];
        self::protect($pdo,$checks,'pa_system_menu',$system,['menu_key','module_key','parent_key']); self::protect($pdo,$checks,'pa_menu_definition',$definition,['upstream_defaults_json']);
        $null=self::ids($nullIds); $parents=self::ids($parentIds);
        self::check($pdo,$checks,"SELECT id,$key AS v FROM pa_system_menu WHERE id NOT IN ($null) ORDER BY id","SELECT id,menu_key AS v FROM pa_system_menu WHERE id NOT IN ($null) ORDER BY id");
        $moduleCase='CASE id'; foreach ($canonical as $row) { $moduleCase.=' WHEN '.(int)$row['id'].' THEN '.$pdo->quote($row['module_key']); }
        $moduleCase=$canonical===[]?$module:"$moduleCase ELSE $module END";
        self::check($pdo,$checks,"SELECT id,$moduleCase AS v FROM pa_system_menu ORDER BY id",'SELECT id,module_key AS v FROM pa_system_menu ORDER BY id');
        self::check($pdo,$checks,"SELECT id,$parent AS v FROM pa_system_menu WHERE id NOT IN ($parents) ORDER BY id","SELECT id,parent_key AS v FROM pa_system_menu WHERE id NOT IN ($parents) ORDER BY id");
        self::check($pdo,$checks,"SELECT id,CASE WHEN upstream_defaults_json IS NOT NULL AND JSON_EXTRACT(upstream_defaults_json,'$.is_show') IS NULL THEN JSON_SET(upstream_defaults_json,'$.is_show',1,'$.is_cache',0,'$.is_disable',0) ELSE upstream_defaults_json END AS v FROM pa_menu_definition ORDER BY id",'SELECT id,upstream_defaults_json AS v FROM pa_menu_definition ORDER BY id');
        return ['checks'=>$checks,'candidates'=>$canonical,'custom_ids'=>array_values(array_diff($nullIds,array_column($canonical,'id'))),'parent_ids'=>$parentIds,
            'added_flags'=>array_values(array_diff(['is_show','is_cache','is_disable'],array_keys($definition)))];
    }

    private static function afterIdentities(PDO $pdo,array $state): void
    {
        self::requireColumns($pdo,'pa_system_menu',['menu_key'=>'varchar(160)','parent_key'=>'varchar(160)','module_key'=>'varchar(96)']);
        if (self::columns($pdo,'pa_system_menu')['menu_key']['IS_NULLABLE']!=='NO') { self::fail('MENU_KEY_NULLABLE'); }
        self::requireColumns($pdo,'pa_menu_definition',['is_show'=>'tinyint','is_cache'=>'tinyint','is_disable'=>'tinyint']);
        foreach ($state['added_flags'] as $flag) { self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_menu_definition WHERE NOT ('.self::quote($flag).' <=> '.($flag==='is_show'?'1':'0').')'); }
        self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu WHERE menu_key IS NULL'); self::assertZero($pdo,'SELECT COUNT(*) AS n FROM (SELECT menu_key FROM pa_system_menu GROUP BY menu_key HAVING COUNT(*)>1) duplicates');
        foreach ($state['candidates'] as $row) { self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu WHERE id='.(int)$row['id'].' AND NOT (BINARY menu_key=BINARY '.$pdo->quote($row['menu_key']).' AND BINARY module_key=BINARY '.$pdo->quote($row['module_key']).')'); }
        self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu WHERE id IN ('.self::ids($state['custom_ids']).") AND NOT REGEXP_LIKE(menu_key,'^custom[.][0-9a-f]{32}$','c')");
        self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu m LEFT JOIN pa_system_menu p ON p.id=m.pid WHERE m.id IN ('.self::ids($state['parent_ids']).') AND NOT (BINARY m.parent_key<=>BINARY p.menu_key)');
        $index=self::query($pdo,"SELECT COLUMN_NAME,NON_UNIQUE,SUB_PART FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_system_menu' AND INDEX_NAME='uk_system_menu_key' ORDER BY SEQ_IN_INDEX");
        if (count($index)!==1||$index[0]['COLUMN_NAME']!=='menu_key'||(string)$index[0]['NON_UNIQUE']!=='0'||$index[0]['SUB_PART']!==null) { self::fail('KEY_UNIQUE_INDEX'); }
        self::assertCustomIdAllocation($pdo);
    }

    private static function assertCustomIdAllocation(PDO $pdo): void
    {
        // TABLES.AUTO_INCREMENT is cached for 24 hours by default. Observe the
        // current storage-engine allocation on this PDO, then restore its setting.
        $expiry=self::query($pdo,'SELECT @@SESSION.information_schema_stats_expiry AS expiry')[0]['expiry'];
        if (!is_int($expiry)&&!(is_string($expiry)&&ctype_digit($expiry))) { self::fail('STATISTICS_SESSION_INVALID'); }
        try {
            $pdo->exec('SET SESSION information_schema_stats_expiry=0');
            $allocation=self::query($pdo,"SELECT AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='pa_system_menu'")[0]['AUTO_INCREMENT'];
        } finally { $pdo->exec('SET SESSION information_schema_stats_expiry='.(string)$expiry); }
        if ($allocation===null||(int)$allocation<1000000000) { self::fail('CUSTOM_ID_ALLOCATION_RANGE'); }
    }

    private static function beforeRepair(PDO $pdo): array
    {
        $counts=self::query($pdo,"SELECT SUM(type='M' AND paths='/app-setting') AS group_count,MIN(IF(type='M' AND paths='/app-setting',id,NULL)) AS group_id,SUM(perms='setting/transaction/config') AS configs,MIN(IF(perms='setting/transaction/config',id,NULL)) AS config_id,SUM(perms='setting/transaction/save') AS saves,MIN(IF(perms='setting/transaction/save',id,NULL)) AS save_id FROM pa_system_menu")[0]; $candidates=[];
        if ((int)$counts['group_count']===1&&(int)$counts['configs']===1) {
            $group=(int)$counts['group_id']; $config=(int)$counts['config_id'];
            $common="child.icon='' AND child.sort=0 AND child.is_cache=0 AND child.is_show=1 AND child.is_disable=0 AND child.module_key='application' AND child.menu_key LIKE 'custom.%' AND child.upstream_defaults_json IS NULL AND child.menu_conflict_json IS NULL";
            $rows=self::query($pdo,"SELECT child.id,parent.id AS pid,parent.menu_key AS parent_key FROM pa_system_menu child JOIN pa_system_menu wrong_parent ON wrong_parent.id=child.pid AND wrong_parent.menu_key=child.parent_key JOIN pa_system_menu parent ON parent.id=$group WHERE child.id=$config AND child.perms='setting/transaction/config' AND child.name='交易设置' AND child.type='C' AND child.paths='/app-setting/transaction' AND child.component='app-setting/transaction/index' AND $common AND wrong_parent.menu_key='core.organization' AND wrong_parent.paths='/system' AND parent.menu_key IS NOT NULL AND parent.menu_key<>''"); $candidates=$rows;
            if ((int)$counts['saves']===1) {
                // Second-statement parent condition observes the first repair, or the original already-correct config.
                $configParent=$rows!==[]?'1=1':'parent.pid=group_parent.id AND parent.parent_key=group_parent.menu_key'; $save=(int)$counts['save_id'];
                $candidates=array_merge($candidates,self::query($pdo,"SELECT child.id,parent.id AS pid,parent.menu_key AS parent_key FROM pa_system_menu child JOIN pa_system_menu wrong_parent ON wrong_parent.id=child.pid AND wrong_parent.menu_key=child.parent_key JOIN pa_system_menu parent ON parent.id=$config JOIN pa_system_menu group_parent ON group_parent.id=$group WHERE child.id=$save AND child.perms='setting/transaction/save' AND child.name='交易设置保存' AND child.type='A' AND child.paths='' AND child.component='' AND $common AND wrong_parent.menu_key='system.menu.add' AND wrong_parent.perms='menu/add' AND parent.perms='setting/transaction/config' AND parent.type='C' AND parent.paths='/app-setting/transaction' AND $configParent"));
            }
        }
        $checks=[]; $ids=self::ids(array_column($candidates,'id')); self::protect($pdo,$checks,'pa_system_menu',self::columns($pdo,'pa_system_menu'),['pid','parent_key']);
        self::check($pdo,$checks,"SELECT id,pid,parent_key FROM pa_system_menu WHERE id NOT IN ($ids) ORDER BY id","SELECT id,pid,parent_key FROM pa_system_menu WHERE id NOT IN ($ids) ORDER BY id"); self::protect($pdo,$checks,'pa_menu_definition',self::columns($pdo,'pa_menu_definition'),[]);
        return ['checks'=>$checks,'candidates'=>$candidates];
    }

    private static function afterRepair(PDO $pdo,array $state): void
    {
        foreach ($state['candidates'] as $row) { $key=$row['parent_key']===null?'NULL':$pdo->quote($row['parent_key']); self::assertZero($pdo,'SELECT COUNT(*) AS n FROM pa_system_menu WHERE id='.(int)$row['id'].' AND NOT (pid='.(int)$row['pid']." AND BINARY parent_key<=>BINARY $key)"); }
    }

    private static function live(): string { return "JSON_OBJECT('pid',pid,'type',type,'name',name,'icon',icon,'sort',sort,'perms',perms,'paths',paths,'component',component,'is_cache',is_cache,'is_show',is_show,'is_disable',is_disable)"; }
    private static function managed(PDO $pdo,int $id,string $baseline): bool { $rows=self::query($pdo,'SELECT ('.self::live()."=$baseline) AS managed FROM pa_system_menu WHERE id=$id"); return count($rows)===1&&(string)$rows[0]['managed']==='1'; }
    private static function columns(PDO $pdo,string $table): array
    {
        $result=[]; foreach (self::query($pdo,'SELECT COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,EXTRA,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='.$pdo->quote($table).' ORDER BY ORDINAL_POSITION') as $column) { $result[$column['COLUMN_NAME']]=$column; } if ($result===[]) { self::fail('TABLE_MISSING'); } return $result;
    }
    private static function column(array $columns,string $name,string $fallback): string { return isset($columns[$name])?self::quote($name):$fallback; }
    private static function requireColumns(PDO $pdo,string $table,array $required): void { $columns=self::columns($pdo,$table); foreach ($required as $name=>$type) { if (!isset($columns[$name])||!str_starts_with(strtolower($columns[$name]['COLUMN_TYPE']),$type)) { self::fail('TARGET_COLUMN_METADATA'); } } }
    private static function protect(PDO $pdo,array &$checks,string $table,array $columns,array $except,string $where='1=1'): void
    {
        $fields=[]; foreach ($columns as $name=>$column) { if (!in_array($name,$except,true)) { $fields[]=self::quote($name); } } $select='SELECT '.implode(',',$fields).' FROM '.self::quote($table)." WHERE $where ORDER BY id"; self::check($pdo,$checks,$select,$select);
    }
    private static function check(PDO $pdo,array &$checks,string $before,string $after): void { $checks[]=['after'=>$after,'digest'=>self::digest($pdo,$before)]; }
    /** Streaming only: no original/expected table copies. String fetching preserves server numeric precision. */
    private static function digest(PDO $pdo,string $select): string
    {
        $stringify=$pdo->getAttribute(PDO::ATTR_STRINGIFY_FETCHES); $statement=null; $hash=hash_init('sha256');
        try { $pdo->setAttribute(PDO::ATTR_STRINGIFY_FETCHES,true); $statement=$pdo->query($select); while (($row=$statement->fetch(PDO::FETCH_NUM))!==false) { foreach ($row as $value) { hash_update($hash,$value===null?'N;':'S'.strlen($value).':'.$value.';'); } hash_update($hash,"\n"); } return hash_final($hash); }
        finally { $statement?->closeCursor(); $pdo->setAttribute(PDO::ATTR_STRINGIFY_FETCHES,$stringify); }
    }
    private static function assertZero(PDO $pdo,string $sql): void { if ((int)self::query($pdo,$sql)[0]['n']!==0) { self::fail('BUSINESS_POSTSTATE'); } }
    private static function ids(array $ids): string { return $ids===[]?'0':implode(',',array_map(static fn($id): string=>(string)(int)$id,$ids)); }
    private static function quote(string $name): string { return '`'.str_replace('`','``',$name).'`'; }
    private static function connection(PDO $pdo): array { return self::query($pdo,'SELECT DATABASE() AS database_name,@@server_uuid AS server_uuid,CONNECTION_ID() AS connection_id')[0]; }
    private static function snapshot(PDO $pdo,Closure $read): array
    {
        $started=false;
        try { if ($pdo->getAttribute(PDO::ATTR_DRIVER_NAME)!=='mysql'||$pdo->getAttribute(PDO::ATTR_CASE)!==PDO::CASE_NATURAL||$pdo->inTransaction()) { self::fail('OWN_READONLY_SNAPSHOT_REQUIRED'); } $pdo->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY'); $pdo->beginTransaction(); $started=true; $result=$read(); $pdo->rollBack(); $started=false; return $result; }
        catch (Throwable $error) { if ($started&&$pdo->inTransaction()) { try { $pdo->rollBack(); } catch (Throwable $close) { throw new RuntimeException('IDENTITY_MENU_MIGRATION_SNAPSHOT_CLOSE_FAILED',0,$close); } } if ($error instanceof RuntimeException&&str_starts_with($error->getMessage(),'IDENTITY_MENU_MIGRATION_')) { throw $error; } throw new RuntimeException('IDENTITY_MENU_MIGRATION_OBSERVATION_FAILED',0,$error); }
    }
    private static function query(PDO $pdo,string $sql): array { $statement=$pdo->query($sql); try { return $statement->fetchAll(PDO::FETCH_ASSOC); } finally { $statement->closeCursor(); } }
    private static function fail(string $reason): never { throw new RuntimeException('IDENTITY_MENU_MIGRATION_'.$reason); }
}
